$b192 = ''
$b512 = ''
$manifest = @'
{
  "name": "Trove - Food & Cake Shop",
  "short_name": "Trove",
  "description": "Trove sales and inventory system",
  "start_url": "/",
  "scope": "/",
  "display": "standalone",
  "orientation": "portrait-primary",
  "background_color": "#FDF6EC",
  "theme_color": "#4A2C17",
  "icons": [
    { "src": "/icons/trove-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any maskable" },
    { "src": "/icons/trove-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any maskable" }
  ]
}
'@
$sw = @'
const CACHE = 'trove-v1';
self.addEventListener('install', function (e) { self.skipWaiting(); });
self.addEventListener('activate', function (e) { e.waitUntil(self.clients.claim()); });
self.addEventListener('fetch', function (e) {
  if (e.request.method !== 'GET') return;
  e.respondWith(
    fetch(e.request).then(function (res) {
      try { var copy = res.clone(); caches.open(CACHE).then(function (c) { c.put(e.request, copy); }); } catch (x) {}
      return res;
    }).catch(function () { return caches.match(e.request); })
  );
});
'@
$headtags = @'
    <link rel="manifest" href="/manifest.webmanifest">
    <meta name="theme-color" content="#4A2C17">
    <meta name="mobile-web-app-capable" content="yes">
    <meta name="apple-mobile-web-app-capable" content="yes">
    <meta name="apple-mobile-web-app-title" content="Trove">
    <link rel="apple-touch-icon" href="/icons/trove-192.png">
'@
$swreg = @'
    <script>
      if ('serviceWorker' in navigator) {
        window.addEventListener('load', function () {
          navigator.serviceWorker.register('/sw.js').catch(function () {});
        });
      }
    </script>
'@

# ============================================================
#  TROVE - Make it an installable PWA (install icon like Draw.io)
#     powershell -ExecutionPolicy Bypass -File setup-pwa.ps1
#  Adds manifest + service worker + icons, and links them in the
#  app layout and the login page. Online already has HTTPS (Render),
#  so the browser's install icon appears once this is deployed.
#  Backs up edited blade files to .bak (keeps existing .bak).
# ============================================================
$ErrorActionPreference = "Stop"
$root = $PSScriptRoot
if ([string]::IsNullOrEmpty($root)) { $root = Get-Location }
if (-not (Test-Path (Join-Path $root "artisan"))) {
    Write-Host "ERROR: run from your project root (where artisan is)." -ForegroundColor Red; exit 1
}
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
function BackupOnce($p){ $b=$p+".bak"; if((Test-Path $p) -and -not(Test-Path $b)){ Copy-Item $p $b } }

# ---------- icons ----------
$iconsDir = Join-Path $root "public\icons"
New-Item -ItemType Directory -Force -Path $iconsDir | Out-Null
[System.IO.File]::WriteAllBytes((Join-Path $iconsDir "trove-192.png"), [System.Convert]::FromBase64String($b192))
[System.IO.File]::WriteAllBytes((Join-Path $iconsDir "trove-512.png"), [System.Convert]::FromBase64String($b512))
Write-Host "  wrote public/icons/trove-192.png + trove-512.png" -ForegroundColor Green

# ---------- manifest ----------
[System.IO.File]::WriteAllText((Join-Path $root "public\manifest.webmanifest"), $manifest, $Utf8NoBom)
Write-Host "  wrote public/manifest.webmanifest" -ForegroundColor Green

# ---------- service worker ----------
[System.IO.File]::WriteAllText((Join-Path $root "public\sw.js"), $sw, $Utf8NoBom)
Write-Host "  wrote public/sw.js" -ForegroundColor Green

# ---------- inject into blade files ----------
$viewport = '    <meta name="viewport" content="width=device-width, initial-scale=1">'
$targets = @(
    (Join-Path $root "resources\views\layouts\app.blade.php"),
    (Join-Path $root "resources\views\auth\login.blade.php")
)
foreach ($t in $targets) {
    if (-not (Test-Path $t)) { Write-Host "  skip (not found): $t" -ForegroundColor DarkGray; continue }
    BackupOnce $t
    $c = ([System.IO.File]::ReadAllText($t)) -replace "`r`n", "`n"
    $changed = $false
    if ($c -notmatch "manifest\.webmanifest" -and $c.Contains($viewport)) {
        $c = $c.Replace($viewport, $viewport + "`n" + $headtags)
        $changed = $true
    }
    if ($c -notmatch "serviceWorker" -and $c.Contains("</head>")) {
        $c = $c.Replace("</head>", $swreg + "`n</head>")
        $changed = $true
    }
    if ($changed) {
        [System.IO.File]::WriteAllText($t, $c, $Utf8NoBom)
        Write-Host ("  linked PWA tags in " + (Split-Path $t -Leaf)) -ForegroundColor Green
    } else {
        Write-Host ("  " + (Split-Path $t -Leaf) + ": already linked or anchors missing") -ForegroundColor DarkGray
    }
}

Write-Host ""
php artisan view:clear
php artisan optimize:clear

Write-Host ""
Write-Host "DONE locally. PWA install works best over HTTPS (your Render site)." -ForegroundColor Cyan
Write-Host "Push to go live:" -ForegroundColor Cyan
Write-Host "  git add public/manifest.webmanifest public/sw.js public/icons resources/views/layouts/app.blade.php resources/views/auth/login.blade.php" -ForegroundColor White
Write-Host "  git commit -m ""Add installable PWA (manifest, service worker, icons)""" -ForegroundColor White
Write-Host "  git push" -ForegroundColor White
